$::jsonb) as t(key text, kind text, u text, m text, it int, loc text, rel int, tm text, dur int, buf int, st text, sd text, sub int, tot int, dep int, pay text, ps text, det jsonb, cb text, cr text, sent text, sago int, ansm int, ans text, done text, canc text, pax int, g jsonb, ord int) order by t.ord) t
 where not exists (select 1 from operations o where o.business_id = 'entrenamiento-personal-carlos-vargas-hazleton' and o.client_key = md5(t.key)::uuid)
on conflict (user_id, client_key) do nothing;
insert into operations (number, kind, city_id, business_id, user_id, member_id, status, status_detail, scheduled_at, duration_min, buffer_min, details, subtotal_cents, total_cents, deposit_cents, pay_mode, pay_status,
                        sent_at, answered_at, confirmed_at, done_at, cancelled_at, cancelled_by, cancel_reason, party_size, client_key, is_test, updated_at)
select 'I-' || nextval('insc_seq'), t.kind, 'alw', 'cuerpo-y-mente-con-mayra-allentown', (select u.id from users u where u.phone = t.u), case when t.m is null then null else md5(t.m)::uuid end, t.st, t.sd, case when t.rel is not null then ((((now() at time zone 'America/New_York')::date + t.rel) + t.tm::time) at time zone 'America/New_York') else (t.loc::timestamp at time zone 'America/New_York') end, t.dur, t.buf,
       t.det || jsonb_build_object('svcId', (select i.id from items i where i.business_id = 'cuerpo-y-mente-con-mayra-allentown' and i.module = 'svc' and i.sort = t.it)::text, 'item_id', (select i.id from items i where i.business_id = 'cuerpo-y-mente-con-mayra-allentown' and i.module = 'svc' and i.sort = t.it)::text) || case when t.g is null then '{}'::jsonb else jsonb_build_object('group_id', (select g.id::text from class_groups g where g.business_id = 'cuerpo-y-mente-con-mayra-allentown' and g.item_id = (select i.id from items i where i.business_id = 'cuerpo-y-mente-con-mayra-allentown' and i.module = 'svc' and i.sort = t.it) and g.label->>'es' = t.g->>'label' and g.starts_on = (t.g->>'starts')::date)) end, t.sub, t.tot, t.dep, t.pay, t.ps, case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end, case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end, case when t.st in ('confirmed', 'done') then case when t.ans is not null then (t.ans::timestamp at time zone 'America/New_York') when t.ansm is not null then (case when t.sent is not null then (t.sent::timestamp at time zone 'America/New_York') else now() - t.sago * interval '1 minute' end) + t.ansm * interval '1 minute' end end,
